CREATE TABLE users (id TEXT PRIMARY KEY, display_name TEXT, role TEXT NOT NULL CHECK(role IN ('participant','admin')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE local_credentials (user_id TEXT PRIMARY KEY REFERENCES users(id), email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, csrf_hash TEXT NOT NULL, created_at TEXT NOT NULL, expires_at REAL NOT NULL, revoked_at TEXT);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE installation (id INTEGER PRIMARY KEY CHECK(id=1), setup_completed_at TEXT NOT NULL);
CREATE TABLE projects (id TEXT PRIMARY KEY, identifier TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL, webhook_url TEXT, webhook_enabled INTEGER NOT NULL DEFAULT 0, webhook_events TEXT NOT NULL DEFAULT '[]', webhook_secret TEXT, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE boards (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), identifier TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(project_id,identifier));
CREATE TABLE external_identities (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), external_user_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(project_id,external_user_id));
CREATE TABLE requests (id TEXT PRIMARY KEY, board_id TEXT NOT NULL REFERENCES boards(id), creator_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 200), description TEXT NOT NULL CHECK(length(description)<=20000), moderation TEXT NOT NULL CHECK(moderation IN ('pending','accepted','rejected')), status TEXT CHECK(status IN ('under_consideration','planned','in_progress','shipped')), accepted_at TEXT, accepted_by TEXT, rejection_reason TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, CHECK((moderation='accepted' AND status IS NOT NULL AND accepted_at IS NOT NULL) OR (moderation!='accepted' AND status IS NULL AND accepted_at IS NULL)));
CREATE TRIGGER accepted_immutable BEFORE UPDATE OF accepted_at ON requests WHEN OLD.accepted_at IS NOT NULL AND NEW.accepted_at IS NOT OLD.accepted_at BEGIN SELECT RAISE(ABORT,'accepted_at is immutable'); END;
CREATE INDEX requests_board_moderation ON requests(board_id,moderation,created_at,id);
CREATE INDEX requests_creator ON requests(creator_id,created_at,id);
CREATE INDEX requests_status ON requests(status,created_at,id) WHERE moderation='accepted';
CREATE TABLE votes (request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, PRIMARY KEY(request_id,user_id));
CREATE INDEX votes_user ON votes(user_id,request_id);
CREATE TABLE api_keys (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, secret_hash TEXT NOT NULL UNIQUE, prefix TEXT NOT NULL, permissions TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, revoked_at TEXT);
CREATE TABLE request_events (id TEXT PRIMARY KEY, type TEXT NOT NULL, schema_version INTEGER NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id), board_id TEXT, request_id TEXT, actor TEXT NOT NULL, occurred_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE INDEX events_request ON request_events(request_id,occurred_at,id);
CREATE TABLE webhook_deliveries (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES request_events(id), destination TEXT NOT NULL, signing_secret TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','delivering','succeeded','failed')), attempt_count INTEGER NOT NULL DEFAULT 0, next_attempt_at REAL NOT NULL, lease_until REAL, lease_token TEXT, last_attempt_at TEXT, last_http_status INTEGER, error TEXT, delivered_at TEXT);
CREATE INDEX deliveries_due ON webhook_deliveries(state,next_attempt_at,lease_until);
CREATE INDEX deliveries_event ON webhook_deliveries(event_id);
